Operazioni Fondamentali di Eigen
#include &lt;Eigen/Dense&gt;

Eigen::MatrixXd W = Eigen::MatrixXd::Random(3, 4); // 3x4, valori in [-1,1]
Eigen::VectorXd x = Eigen::VectorXd::Random(4);    // 4x1

// Prodotto matrice-vettore → risultato 3x1
Eigen::VectorXd z = W * x;

// Trasposta
Eigen::MatrixXd Wt = W.transpose();  // diventa 4x3

// Inizializzazioni utili
Eigen::MatrixXd Z = Eigen::MatrixXd::Zero(3, 4);
Eigen::MatrixXd I = Eigen::MatrixXd::Identity(4, 4);

// Operazioni ELEMENTO PER ELEMENTO con .array()
// (indispensabile per le funzioni di attivazione!)
Eigen::ArrayXd relu = z.array().max(0.0);   // ReLU: max(0, zi)
Eigen::ArrayXd sig  = 1.0 / (1.0 + (-z.array()).exp()); // Sigmoid
Attenzione: * tra due MatrixXd è sempre prodotto matriciale. Per il prodotto elemento per elemento usate .array().

