#define MATRIX_HPP

class Matrix {
private:
    int rows;
    int cols;
    double* data;        // un unico blocco contiguo, row-major

public:
    Matrix(int r, int c);

    double get(int r, int c) const;
    void set(int r, int c, double val);

    int getRows() const;
    int getCols() const;
};

