// const auto& perché le stringhe sono pesanti da copiare!
for (const auto& coppia : config) { 
    std::cout &lt;&lt; "Parametro: " &lt;&lt; coppia.first 
              &lt;&lt; " | Valore: " &lt;&lt; coppia.second &lt;&lt; "\n";
}

